// Contract (input): { system, user, model?, temperature?, max_tokens?, json?:bool }
// Provider-neutral shape; body follows OpenAI/OpenRouter chat schema.
const i = $json || {};
if (!i.user) throw new Error('llm-complete: `user` is required');
const messages = [];
if (i.system) messages.push({ role: 'system', content: String(i.system) });
messages.push({ role: 'user', content: String(i.user) });
const body = {
  model: i.model || $env.LLM_DEFAULT_MODEL || 'openai/gpt-4o-mini',
  messages,
  temperature: i.temperature ?? 0.2,
  max_tokens: i.max_tokens ?? 1024
};
if (i.json) body.response_format = { type: 'json_object' };
return [{ json: { body } }];

// Output contract: { content, model, usage, raw }
const r = $json;
const choice = r.choices && r.choices[0];
if (!choice) throw new Error('llm-complete: no choices in response: ' + JSON.stringify(r).slice(0,500));
return [{ json: {
  content: choice.message?.content ?? '',
  model: r.model || null,
  usage: r.usage || null,
  finish_reason: choice.finish_reason || null
}}];
